using SpaceBattle.Lib;

namespace SpaceBattle.Tests;

public class CollisionFileTests
{
    [Fact]
    public void Parse_Reads_Vectors_And_Skips_Comments_And_Blank_Lines()
    {
        var vectors = CollisionFile.Parse(
        [
            "# generated by generate_collisions.py",
            "# dx dy dvx dvy",
            "",
            "  3 -2 1 0  ",
            "-4\t5\t-6\t7",
            "   ",
            "0 0 0 0"
        ]).ToList();

        Assert.Equal(3, vectors.Count);
        Assert.Equal("3 -2 1 0", string.Join(' ', vectors[0]));
        Assert.Equal("-4 5 -6 7", string.Join(' ', vectors[1]));
        Assert.Equal("0 0 0 0", string.Join(' ', vectors[2]));
    }

    [Fact]
    public void Parse_Of_Empty_Input_Is_Empty()
    {
        Assert.Empty(CollisionFile.Parse([]));
        Assert.Empty(CollisionFile.Parse(["# only a header"]));
    }

    [Theory]
    [InlineData("1 2 3")]
    [InlineData("1 2 3 4 5")]
    [InlineData("1 2 x 4")]
    [InlineData("1,2,3,4")]
    [InlineData("1 2 3 4.5")]
    public void Parse_Rejects_Malformed_Lines_And_Reports_The_Line_Number(string line)
    {
        var error = Assert.Throws<FormatException>(() => CollisionFile.Parse(["# header", "1 2 3 4", line]).ToList());

        Assert.StartsWith("Line 3:", error.Message);
    }

    [Fact]
    public void Parse_Is_Lazy_And_Reports_Errors_Only_When_Enumerated()
    {
        var vectors = CollisionFile.Parse(["broken"]);

        Assert.Throws<FormatException>(() => vectors.ToList());
    }
}
